class DeviceCredentialResource extends JsonResource { public function toArray(Request $request):array{return ['id'=>(string)$this->id,'name'=>$this->name,'prefix'=>$this->token_prefix,'scopes'=>$this->scopes,'device'=>$this->device?['id'=>(string)$this->device->id,'name'=>$this->device->name,'identifier'=>$this->device->external_id]:null,'createdBy'=>$this->creator?['id'=>(string)$this->creator->id,'name'=>$this->creator->name]:null,'createdAt'=>$this->created_at?->toISOString(),'lastUsedAt'=>$this->last_used_at?->toISOString(),'expiresAt'=>$this->expires_at?->toISOString(),'revokedAt'=>$this->revoked_at?->toISOString(),'status'=>$this->revoked_at?'revoked':($this->expires_at?->isPast()?'expired':'active')];} }
